import { NextResponse } from 'next/server';
import { buildAuthorizeUrl } from '@/lib/uber/oauth';
import { setOAuthState } from '@/lib/uber/session';
import { ConfigError } from '@/lib/uber/config';

/** Starts the OAuth flow by redirecting the user to Uber's consent screen. */
export async function GET() {
  try {
    const state = crypto.randomUUID();
    await setOAuthState(state);
    return NextResponse.redirect(buildAuthorizeUrl(state));
  } catch (error) {
    if (error instanceof ConfigError) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }
    throw error;
  }
}

import { NextResponse } from 'next/server';
import {
  getAccessToken,
  getGrantedScopes,
  getRefreshToken,
} from '@/lib/uber/session';

/**
 * Lets the browser discover whether a session exists, and which scopes it
 * carries, without ever exposing the token itself.
 */
export async function GET() {
  const [accessToken, refreshToken, scopes] = await Promise.all([
    getAccessToken(),
    getRefreshToken(),
    getGrantedScopes(),
  ]);

  return NextResponse.json({
    authenticated: Boolean(accessToken || refreshToken),
    /** Empty when Uber did not report a scope list on the token response. */
    scopes,
    /** Whether the session can outlive the current access token. */
    canRefresh: Boolean(refreshToken),
  });
}

import { NextResponse } from 'next/server';
import { clearSession } from '@/lib/uber/session';

export async function POST() {
  await clearSession();
  return NextResponse.json({ ok: true });
}

'use client';

import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useState,
} from 'react';
import type { AdAccount } from '@/types/api';
import { getSession, logout as endSession } from '@/lib/auth';
import { uberAds, UberApiError } from '@/lib/api';

const SELECTED_ACCOUNT_KEY = 'uber_ads_selected_account_id';

interface AuthContextValue {
  /** `null` while the session check is still in flight. */
  isAuthenticated: boolean | null;
  adAccounts: AdAccount[];
  selectedAdAccount: AdAccount | null;
  isLoading: boolean;
  error: string | null;
  /** Scopes Uber granted. Empty if the token response omitted them. */
  grantedScopes: string[];
  /**
   * Whether a scope was granted. Returns `true` when the granted list is
   * unknown, so features are never hidden on incomplete information.
   */
  hasScope: (scope: string) => boolean;
  logout: () => Promise<void>;
  selectAdAccount: (account: AdAccount) => void;
  refreshAdAccounts: () => Promise<void>;
}

const AuthContext = createContext<AuthContextValue | undefined>(undefined);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean | null>(null);
  const [adAccounts, setAdAccounts] = useState<AdAccount[]>([]);
  const [selectedAdAccount, setSelectedAdAccount] = useState<AdAccount | null>(
    null
  );
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [grantedScopes, setGrantedScopes] = useState<string[]>([]);

  const loadAdAccounts = useCallback(async () => {
    setIsLoading(true);
    setError(null);

    try {
      const { ad_accounts } = await uberAds.getAdAccounts();
      const accounts = ad_accounts ?? [];
      setAdAccounts(accounts);

      // Restore the previously chosen account, otherwise fall back to the
      // first one so the dashboard always has something to render.
      const storedId =
        typeof window === 'undefined'
          ? null
          : localStorage.getItem(SELECTED_ACCOUNT_KEY);
      setSelectedAdAccount(
        accounts.find((account) => account.ad_account_id === storedId) ??
          accounts[0] ??
          null
      );
    } catch (cause) {
      if (cause instanceof UberApiError && cause.isUnauthenticated) {
        setIsAuthenticated(false);
      }
      setError(
        cause instanceof Error ? cause.message : 'Failed to load ad accounts.'
      );
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    let cancelled = false;

    getSession().then(async (session) => {
      if (cancelled) return;
      setIsAuthenticated(session.authenticated);
      setGrantedScopes(session.scopes);
      if (session.authenticated) {
        await loadAdAccounts();
      } else {
        setIsLoading(false);
      }
    });

    return () => {
      cancelled = true;
    };
  }, [loadAdAccounts]);

  const logout = useCallback(async () => {
    localStorage.removeItem(SELECTED_ACCOUNT_KEY);
    setAdAccounts([]);
    setSelectedAdAccount(null);
    setGrantedScopes([]);
    setIsAuthenticated(false);
    await endSession();
  }, []);

  const hasScope = useCallback(
    (scope: string) =>
      grantedScopes.length === 0 || grantedScopes.includes(scope),
    [grantedScopes]
  );

  const selectAdAccount = useCallback((account: AdAccount) => {
    setSelectedAdAccount(account);
    if (account.ad_account_id) {
      localStorage.setItem(SELECTED_ACCOUNT_KEY, account.ad_account_id);
    }
  }, []);

  return (
    <AuthContext.Provider
      value={{
        isAuthenticated,
        adAccounts,
        selectedAdAccount,
        isLoading,
        error,
        grantedScopes,
        hasScope,
        logout,
        selectAdAccount,
        refreshAdAccounts: loadAdAccounts,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

/**
 * Browser-side session helpers.
 *
 * Tokens are held in httpOnly cookies, so this module cannot read them. It
 * only asks the server whether a session exists and triggers login/logout.
 */

/** Full-page navigation to the server route that redirects to Uber. */
export function startLogin(): void {
  window.location.href = '/api/auth/login';
}

export interface Session {
  authenticated: boolean;
  /** Scopes Uber actually granted, which may be fewer than were requested. */
  scopes: string[];
  canRefresh: boolean;
}

const NO_SESSION: Session = {
  authenticated: false,
  scopes: [],
  canRefresh: false,
};

export async function getSession(): Promise<Session> {
  try {
    const response = await fetch('/api/auth/session', { cache: 'no-store' });
    if (!response.ok) return NO_SESSION;
    return (await response.json()) as Session;
  } catch {
    return NO_SESSION;
  }
}

export async function logout(): Promise<void> {
  await fetch('/api/auth/logout', { method: 'POST' });
  window.location.href = '/login';
}

import { OAUTH_ENDPOINTS, requireServerConfig } from './config';
import type { UberTokenResponse } from './session';

/**
 * Uber OAuth 2.0 authorization code flow.
 *
 * Uber does not support the client credentials grant, so a user must approve
 * access in the browser before the API can be called on their behalf.
 * @see https://developer.uber.com/docs/ads/get-started/authentication
 */

export class OAuthError extends Error {
  readonly status: number;
  readonly details: unknown;

  constructor(message: string, status: number, details?: unknown) {
    super(message);
    this.name = 'OAuthError';
    this.status = status;
    this.details = details;
  }
}

export function buildAuthorizeUrl(state: string): string {
  const config = requireServerConfig();

  const params = new URLSearchParams({
    response_type: 'code',
    client_id: config.clientId,
    redirect_uri: config.redirectUri,
    scope: config.scope,
    state,
  });

  return `${OAUTH_ENDPOINTS.authorize(config.authBaseUrl)}?${params}`;
}

async function requestToken(
  params: Record<string, string>
): Promise<UberTokenResponse> {
  const config = requireServerConfig();

  const response = await fetch(OAUTH_ENDPOINTS.token(config.authBaseUrl), {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      client_id: config.clientId,
      client_secret: [REDACTED],
      ...params,
    }),
  });

  const body = await response.text();

  if (!response.ok) {
    let details: unknown = body;
    try {
      details = JSON.parse(body);
    } catch {
      // Uber occasionally returns a plain-text error; keep the raw body.
    }
    throw new OAuthError(
      `Uber token request failed (${response.status})`,
      response.status,
      details
    );
  }

  return JSON.parse(body) as UberTokenResponse;
}

export function exchangeCodeForTokens(code: string): Promise<UberTokenResponse> {
  const config = requireServerConfig();
  return requestToken({
    grant_type: 'authorization_code',
    redirect_uri: config.redirectUri,
    code,
  });
}

export function refreshTokens(refreshToken: string): Promise<UberTokenResponse> {
  return requestToken({
    grant_type: 'refresh_token',
    refresh_token: [REDACTED],
  });
}

import { NextRequest, NextResponse } from 'next/server';
import { exchangeCodeForTokens } from '@/lib/uber/oauth';
import { consumeOAuthState, persistTokens } from '@/lib/uber/session';

/**
 * OAuth redirect target. This path must exactly match the redirect URI
 * registered on your Uber app and the `UBER_REDIRECT_URI` env var.
 *
 * Handling the callback as a route handler (rather than a page) keeps the
 * authorization code and the resulting tokens entirely on the server.
 */
export async function GET(request: NextRequest) {
  const params = request.nextUrl.searchParams;
  const failure = (reason: string) =>
    NextResponse.redirect(
      new URL(`/login?error=${encodeURIComponent(reason)}`, request.url)
    );

  const error = params.get('error');
  if (error) {
    return failure(params.get('error_description') || error);
  }

  const code = params.get('code');
  if (!code) {
    return failure('Uber did not return an authorization code.');
  }

  // Reject the callback unless it carries the state we issued, which prevents
  // an attacker from injecting their own authorization code.
  const expectedState = await consumeOAuthState();
  if (!expectedState || params.get('state') !== expectedState) {
    return failure('OAuth state mismatch. Please start the login flow again.');
  }

  try {
    await persistTokens(await exchangeCodeForTokens(code));
  } catch (cause) {
    const message =
      cause instanceof Error ? cause.message : 'Token exchange failed.';
    return failure(message);
  }

  return NextResponse.redirect(new URL('/dashboard/campaigns', request.url));
}

